package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	fmt.Fscan(in, &n)

	ones := 0
	bestGain := -1
	currentGain := 0

	for i := 0; i < n; i++ {
		var a int
		fmt.Fscan(in, &a)

		gain := 1
		if a == 1 {
			ones++
			gain = -1
		}

		if i == 0 || currentGain+gain < gain {
			currentGain = gain
		} else {
			currentGain += gain
		}

		if currentGain > bestGain {
			bestGain = currentGain
		}
	}

	fmt.Println(ones + bestGain)
}

